/* ===== v2 admin B: cities & zones, live map, communications ===== */
const stateBadge=s=>`<span class="badge ${s==='active'?'ok':s==='soon'?'warn':'neu'}">${s==='active'?'●':'○'} ${t(s==='active'?'Enabled':s==='soon'?'Coming soon':'Disabled')}</span>`;
V.xgeo=()=>{return `<div class="stack-lg"><div class="row between wrap-r"><h1>${t('Cities & zones')}</h1><button class="btn p sm" data-act="cityNew">${ic('plus',16)} ${t('Add new city')}</button></div><p class="t2">${t('Open a city to manage its service area, delivery zones and admins.')}</p><div class="grid auto">${D().cities.map(c=>{const zn=D().zones.filter(z=>z.city===c.id).length,ad=D().admins.filter(a=>a.cities.includes(c.id)).length;return `<div class="card pad stack hover"><div class="row between"><b style="font-size:1.1rem">${esc(nm(c))}</b>${stateBadge(c.state)}</div><div class="row wrap-r small t2" style="gap:12px"><span>${ic('layers',14)} ${zn} ${t('zones')}</span><span>${ic('pin',14)} ${c.areas} ${t('areas')}</span><span>${ic('users',14)} ${ad} ${t('admins')}</span></div><div class="small muted">${t('Waitlist')}: ${S.notifyCity[nm(c)]||(c.state==='active'?0:c.id==='kasia'?48:5)}</div><div class="row"><a class="btn p sm grow" href="#xcity-${c.id}">${t('Open city')} ${ic('cr',14)}</a><button class="btn ${c.state==='active'?'g':'p'} sm" data-act="cityToggle" data-id="${c.id}">${c.state==='active'?t('Disable'):t('Enable')}</button></div></div>`}).join('')}</div></div>`};
A.cityToggle=el=>{const c=D().cities.find(x=>x.id===el.dataset.id),on=c.state==='active';confirmBox(on?`${t('Disable')} ${nm(c)}?`:`${t('Enable')} ${nm(c)}?`,on?t('Customers in this city will see “We are not in your city yet”. Open orders continue, new orders stop.'):t('Customers in this city will be able to browse and order. Make sure zones and admins are set up.'),on?t('Confirm disable'):t('Confirm enable'),()=>{const b=c.state;c.state=on?'soon':'active';audit('City '+(on?'disabled':'enabled'),c.en,{state:b},{state:c.state});save();render(true);toast(`${nm(c)} ${on?t('was disabled'):t('is now enabled')}`,'check')},on)};
F.cityNew=d=>{const id=d.n.toLowerCase().replace(/\W+/g,'')||rid('c');D().cities.push({id,en:d.n,hi:d.n,state:d.s==='active'?'active':d.s,areas:0,lat:26.8,lng:83.9});audit('City added',d.n,{},{state:d.s});save();closeSheet();go('xcity-'+id);toast(t('City added'),'check')};
CH.cityOn=el=>{};
/* city detail */
UI.zed={mode:'idle',zid:'',pts:[]};
function mapWithOverlay(id,o,ov){return mapSvg(id,[],o).replace('</svg></div>',ov+'</svg></div>')}
function zoneMapHtml(city){const ed=UI.zed,center={lat:city.lat,lng:city.lng},zs=D().zones.filter(z=>z.city===city.id),P=p=>mapXY({lat:p[0],lng:p[1]},center),pts=poly=>poly.map(p=>{const q=P(p);return q.x.toFixed(1)+','+q.y.toFixed(1)}).join(' ');
 let ov=zs.map(z=>{const c=z.poly.reduce((a,p)=>[a[0]+p[0]/z.poly.length,a[1]+p[1]/z.poly.length],[0,0]),q=P(c);return `<polygon class="zpoly ${ed.zid===z.id?'sel':''}" points="${pts(z.poly)}" data-zid="${z.id}" style="${z.status==='active'?'':'fill:#888;stroke:#888'}"/><text x="${q.x}" y="${q.y}" text-anchor="middle" font-size="9" font-weight="700" fill="#7C2D12" pointer-events="none">${esc(z.name.split(' (')[0])}</text>`}).join('');
 if(ed.mode==='edit'){const z=zs.find(x=>x.id===ed.zid);if(z)ov+=z.poly.map((p,i)=>{const q=P(p);return `<circle class="zv" data-vi="${i}" cx="${q.x}" cy="${q.y}" r="9" tabindex="0" role="button" aria-label="${t('Corner')} ${i+1}"/>`}).join('')}
 if(ed.mode==='draw'&&ed.pts.length){ov+=`<polyline points="${pts(ed.pts)}" fill="rgba(194,65,12,.12)" stroke="#C2410C" stroke-width="2.5" stroke-dasharray="4 3"/>`+ed.pts.map((p,i)=>{const q=P(p);return `<circle cx="${q.x}" cy="${q.y}" r="7" fill="#C2410C" stroke="#fff" stroke-width="2"/><text x="${q.x}" y="${q.y+3.5}" text-anchor="middle" font-size="8" fill="#fff" pointer-events="none">${i+1}</text>`}).join('')}
 return mapWithOverlay('zmap',{noMe:true,center},ov)}
V.xcity=id=>{const c=D().cities.find(x=>x.id===id);if(!c)return V.nf();const zs=D().zones.filter(z=>z.city===id),ed=UI.zed,ad=D().admins.filter(a=>a.cities.includes(id)),on=c.state==='active';
 post.push(()=>attachZone(c));
 return `<div class="stack-lg"><a class="btn t sm" href="#xgeo" style="justify-self:start">${ic('cl',16)} ${t('All cities')}</a><div class="row between wrap-r"><div class="row"><h1>${esc(nm(c))}</h1>${stateBadge(c.state)}</div><button class="btn ${on?'d':'p'} sm" data-act="cityToggle" data-id="${id}">${on?t('Disable city'):t('Enable city')}</button></div>
 <div class="card pad stack"><div class="row between wrap-r"><h3>${t('Service area & delivery zones')}</h3><div class="row wrap-r">${ed.mode==='draw'?`<button class="btn g sm" data-act="zUndo" ${ed.pts.length?'':'disabled'}>${t('Undo point')}</button><button class="btn p sm" data-act="zFinish" ${ed.pts.length>=3?'':'disabled'}>${t('Finish zone')}</button><button class="btn t sm" data-act="zCancel">${t('Cancel')}</button>`:ed.mode==='edit'?`<button class="btn p sm" data-act="zDone">${ic('check',14)} ${t('Done editing')}</button>`:`<button class="btn p sm" data-act="zDraw">${ic('plus',14)} ${t('Draw new zone')}</button>`}</div></div>
 ${ed.mode==='draw'?alertBox('info',t('Tap the map to place corners. You need at least 3. Then tap “Finish zone”.')):ed.mode==='edit'?alertBox('info',t('Drag a corner to reshape. Double-tap a corner to remove it. Tap the map to add a corner.')):''}
 <div id="zwrap" style="${ed.mode!=='idle'?'cursor:crosshair':''}">${zoneMapHtml(c)}</div></div>
 <div class="card pad stack"><h3>${t('Zones')}</h3>${zs.length?`<div class="stack">${zs.map(z=>`<div class="card pad stack" style="${ed.zid===z.id?'border-color:var(--primary)':''}"><div class="row between wrap-r"><div><b>${esc(z.name)}</b><div class="small t2">${z.slabs.map(s=>`≤ ${s.upto} km: ${inr(s.fee)}`).join(' · ')}</div></div><span class="badge ${z.status==='active'?'ok':'neu'}">${z.status==='active'?'●':'○'} ${t(z.status==='active'?'Active':'Paused')}</span></div><div class="row wrap-r"><button class="btn g sm" data-act="zSel" data-id="${z.id}">${ic('map',14)} ${t('Edit shape')}</button><button class="btn g sm" data-act="zMeta" data-id="${z.id}">${ic('edit',14)} ${t('Name & fees')}</button></div></div>`).join('')}</div>`:empty('🗺️','No zones yet, draw your first zone','Draw an area on the map and set delivery fees for it.','<button class="btn p" data-act="zDraw">'+t('Draw your first zone')+'</button>')}</div>
 <div class="card pad stack"><div class="row between"><h3>${t('Admins assigned to')} ${esc(nm(c))}</h3><a class="btn t sm" href="#xadmins" data-act="adCity" data-id="${id}">${t('Manage')}</a></div>${ad.length?ad.map(a=>`<div class="row between"><span><b>${esc(a.name)}</b> <span class="small t2">· ${esc(a.role)}</span></span><span class="badge ${a.status==='active'?'ok':'neu'}">${t(a.status==='active'?'Active':'Inactive')}</span></div>`).join(''):`<span class="muted small">${t('No admins assigned yet.')}</span>`}</div></div>`};
A.adCity=el=>{UI.xad={q:'',city:el.dataset.id,area:'',role:'',status:'',open:UI.xad.open}};
const redrawZone=()=>{const c=D().cities.find(x=>x.id===cur().arg);const w=$('#zwrap');if(w&&c)w.innerHTML=zoneMapHtml(c)};
function attachZone(c){const w=$('#zwrap');if(!w||w._zb)return;w._zb=1;let drag=-1,moved=false;const toLL=e=>{const svg=w.querySelector('svg'),r=svg.getBoundingClientRect();const x=(e.clientX-r.left)*360/r.width,y=(e.clientY-r.top)*300/r.height;const ll=mapLL(x,y,{lat:c.lat,lng:c.lng});return[ll.lat,ll.lng]};
 w.addEventListener('pointerdown',e=>{const h=e.target.closest('.zv');if(h&&UI.zed.mode==='edit'){drag=+h.dataset.vi;moved=false;w.setPointerCapture(e.pointerId);e.preventDefault();return}
  if(UI.zed.mode==='draw'){UI.zed.pts.push(toLL(e));render(true);return}
  if(UI.zed.mode==='edit'&&!h){const z=D().zones.find(x=>x.id===UI.zed.zid),p=toLL(e);let bi=0,bd=1e9;z.poly.forEach((a,i)=>{const b=z.poly[(i+1)%z.poly.length],d=Math.hypot((a[0]+b[0])/2-p[0],(a[1]+b[1])/2-p[1]);if(d<bd){bd=d;bi=i}});z.poly.splice(bi+1,0,p);save();redrawZone();return}
  const pz=e.target.closest('[data-zid]');if(pz&&UI.zed.mode==='idle'){UI.zed.zid=pz.dataset.zid;render(true)}});
 w.addEventListener('pointermove',e=>{if(drag<0)return;moved=true;const z=D().zones.find(x=>x.id===UI.zed.zid);z.poly[drag]=toLL(e);const keep=drag;redrawZone()});
 w.addEventListener('pointerup',e=>{if(drag>=0){drag=-1;save();redrawZone()}});
 w.addEventListener('dblclick',e=>{const h=e.target.closest('.zv');if(!h||UI.zed.mode!=='edit')return;const z=D().zones.find(x=>x.id===UI.zed.zid);if(z.poly.length<=3){toast(t('A zone needs at least 3 corners'),'alert');return}z.poly.splice(+h.dataset.vi,1);save();redrawZone()});
 w.addEventListener('keydown',e=>{const h=e.target.closest('.zv');if(!h||UI.zed.mode!=='edit')return;const z=D().zones.find(x=>x.id===UI.zed.zid),i=+h.dataset.vi,st=.0008;const mv={ArrowUp:[st,0],ArrowDown:[-st,0],ArrowLeft:[0,-st],ArrowRight:[0,st]}[e.key];if(mv){e.preventDefault();z.poly[i]=[z.poly[i][0]+mv[0],z.poly[i][1]+mv[1]];save();redrawZone();const n=$(`.zv[data-vi="${i}"]`);n&&n.focus()}else if(e.key==='Delete'&&z.poly.length>3){z.poly.splice(i,1);save();redrawZone()}})}
A.zDraw=()=>{UI.zed={mode:'draw',zid:'',pts:[]};render(true)};A.zUndo=()=>{UI.zed.pts.pop();render(true)};A.zCancel=()=>{UI.zed={mode:'idle',zid:'',pts:[]};render(true)};A.zDone=()=>{UI.zed={mode:'idle',zid:UI.zed.zid,pts:[]};render(true);toast(t('Zone shape saved'),'check')};A.zSel=el=>{UI.zed={mode:'edit',zid:el.dataset.id,pts:[]};render(true);window.scrollTo(0,0)};
A.zFinish=()=>zoneSheet({id:'',name:'',slabs:[{upto:2,fee:20},{upto:5,fee:40}],status:'active'},true);
A.zMeta=el=>zoneSheet(D().zones.find(z=>z.id===el.dataset.id),false);
function zoneSheet(z,isNew){sheet(`<h3>${isNew?t('New zone'):t('Edit zone')}</h3><form data-form="zone" class="stack" style="margin-top:10px"><input type="hidden" name="id" value="${z.id}">${field('Zone name','name',z.name,{req:1,ph:'e.g. Hata Road belt'})}<div class="lbl small">${t('Delivery fee slabs')}</div>${[0,1,2].map(i=>{const s=z.slabs[i]||{upto:'',fee:''};return `<div class="grid g2">${field('Up to (km)','u'+i,s.upto,{type:'number',min:0,step:'0.5'})}${field('Fee (₹)','f'+i,s.fee,{type:'number',min:0})}</div>`}).join('')}${field('Status','status',z.status,{type:'select',opts:[['active','Active'],['paused','Paused']]})}<div class="row">${isNew?'':`<button type="button" class="btn d grow" data-act="zDel" data-id="${z.id}">${t('Delete zone')}</button>`}<button class="btn p grow">${t('Save zone')}</button></div></form>`,{label:'Zone'})}
F.zone=d=>{const slabs=[0,1,2].filter(i=>d['u'+i]!==''&&d['u'+i]!==undefined&&!isNaN(+d['u'+i])).map(i=>({upto:+d['u'+i],fee:+d['f'+i]||0})).sort((a,b)=>a.upto-b.upto);const city=cur().arg;if(d.id){const z=D().zones.find(x=>x.id===d.id);Object.assign(z,{name:d.name,slabs,status:d.status});audit('Zone updated',d.name,{},{slabs})}else{const z={id:rid('z'),city,name:d.name,poly:UI.zed.pts.map(p=>[p[0],p[1]]),slabs,status:d.status};D().zones.push(z);UI.zed={mode:'idle',zid:z.id,pts:[]};audit('Zone created',d.name,{},{slabs})}save();closeSheet();render(true);toast(t('Zone saved'),'check')};
A.zDel=el=>confirmBox(t('Delete this zone?'),t('Deliveries inside it will fall back to the city default fees.'),t('Delete zone'),()=>{D().zones=D().zones.filter(z=>z.id!==el.dataset.id);UI.zed={mode:'idle',zid:'',pts:[]};save();closeSheet();render(true);toast(t('Zone deleted'),'trash')},true);
