UI.lv={city:'all'};
function lvItems(city){if(city!=='all'&&city!=='padrauna')return[];const out=[];D().jobs.filter(j=>!['delivered','failed'].includes(j.status)).forEach(j=>{const o=order(j.oid);if(!o)return;const b=biz(o.bid),pos=o.addrPos||addrPos();const p=j.status==='requested'?0:j.status==='pickedUp'?.5:j.status==='reachedDrop'?.95:.1;out.push({id:o.id,rider:j.riderId?rider(j.riderId).name:'—',st:j.status==='requested'?'Waiting for rider':jobLabel(j.status),eta:Math.max(2,Math.round((j.dist||2)*6*(1-p))),city:'padrauna',lat:b.lat+(pos.lat-b.lat)*p,lng:b.lng+(pos.lng-b.lng)*p,wait:j.status==='requested'})});D().liveSyn.forEach(s=>out.push({...s,wait:false}));return out}
const regXY=c=>({x:10+(c.lng-83.2)*340,y:10+(27.0-c.lat)/0.7*280});
V.alive=()=>gate('orders',()=>{const city=UI.lv.city,cities=D().cities,items=lvItems(city),cname=city==='all'?t('All cities'):nm(cities.find(c=>c.id===city)||{en:city});
 const cfg={label:'City',placeholder:'Search cities',value:city,recent:(S.cmRecent&&S.cmRecent.lvc)||[],items:[{id:'all',label:t('All cities'),sub:lvItems('all').length+' '+t('live')},...cities.map(c=>({id:c.id,label:nm(c),sub:lvItems(c.id).length+' '+t('live')}))],onPick:id=>{UI.lv.city=id;render(true)}};
 let map;if(city==='all'){const cl=cities.map(c=>({c,n:lvItems(c.id).length,p:regXY(c)}));map=`<div class="map"><svg viewBox="0 0 360 300" role="img" aria-label="${t('Cities with live deliveries')}"><path d="M0 220 C80 190 140 250 230 210 S340 180 380 195" stroke="#9CC9E8" stroke-width="14" fill="none" opacity=".7"/>${cl.map(({c,n,p})=>`<g class="pin" tabindex="0" role="button" data-act="lvCity" data-id="${c.id}" aria-label="${esc(nm(c))}: ${n} ${t('live deliveries')}" transform="translate(${p.x},${p.y})"><circle r="${n?20:11}" fill="${n?'#C2410C':'#fff'}" fill-opacity="${n?.92:1}" stroke="#C2410C" stroke-width="2.5"/>${n?`<text y="5" text-anchor="middle" font-size="14" font-weight="700" fill="#fff">${n}</text>`:`<text y="4" text-anchor="middle" font-size="10" fill="#C2410C">0</text>`}<text y="${n?34:24}" text-anchor="middle" font-size="9" fill="#6b5b45">${esc(nm(c).split(' (')[0])}</text></g>`).join('')}</svg></div><div class="small muted">${t('Cluster pins show live deliveries per city. Tap one to zoom in.')}</div>`}
 else{const c=cities.find(x=>x.id===city),pins=items.map(i=>({id:i.id,name:{en:'Order '+i.id},emoji:i.wait?'⏳':'🛵',lat:i.lat,lng:i.lng}));map=mapSvg('livemap',pins,{noMe:true,center:{lat:c.lat,lng:c.lng}})}
 return `<div class="stack"><div class="row between wrap-r"><h1><span class="livedot"></span>${t('Live deliveries')}</h1></div><div class="grid g2" style="align-items:end">${comboHtml('lvc',cfg)}<div class="card pad"><b>${items.length}</b> ${t('live deliveries in')} <b>${esc(cname)}</b></div></div><div class="cols2">${map}<div class="stack"><h3>${t('Active deliveries')}</h3>${items.length?items.map(i=>`<div class="card pad row between wrap-r"><div><a href="#aorder-${i.id}" style="color:var(--primary);font-weight:700">${i.id}</a><div class="small t2">${t('Rider')}: ${esc(i.rider)}</div></div><div class="right"><span class="badge info">${t(i.st)}</span><div class="xs muted">${t('ETA')} ${i.eta} ${t('min')}</div></div></div>`).join(''):empty('🛵','No live deliveries in '+cname,'When orders are out for delivery they will appear here.')}</div></div></div>`});
A.lvCity=el=>{UI.lv.city=el.dataset.id;render(true)};
