UI.cm={target:'b1',tpl:'offer',ch:{wa:true,app:true,email:false},sched:'now',when:'',scope:'all',cities:['padrauna'],zones:['z1'],step:'form'};
const allowedScopes=()=>S.role==='super'?['all','city','zone']:(curAdmin().scopes||[]).filter(s=>s==='city'||s==='zone');
const scopeCities=()=>S.role==='super'?D().cities:D().cities.filter(c=>curAdmin().cities.includes(c.id));
const scopeZones=()=>D().zones.filter(z=>scopeCities().some(c=>c.id===z.city));
function scopeFactor(){const c=UI.cm;if(c.scope==='all')return 1;if(c.scope==='city')return Math.min(1,c.cities.reduce((a,id)=>a+(id==='padrauna'?.9:.06),0));return Math.min(1,c.zones.length*.42)}
function scopeText(){const c=UI.cm;if(c.scope==='all')return t('Overall (all cities)');if(c.scope==='city')return t('City-wise')+': '+(c.cities.map(id=>nm(D().cities.find(x=>x.id===id)||{en:id})).join(', ')||'—');return t('Zone-wise')+': '+(c.zones.map(id=>(D().zones.find(x=>x.id===id)||{}).name).filter(Boolean).join(', ')||'—')}
const audOf=()=>{const c=UI.cm,base=c.target[0]==='u'?1:audSize(c.target),n=Math.max(c.target[0]==='u'?1:0,Math.round(base*scopeFactor()));return{n,wa:Math.round(n*.62),app:Math.round(n*.9),em:Math.round(n*.48)}};
V.acomms=()=>gate('comms',()=>{const c=UI.cm,al=allowedScopes();if(!al.length)return noPerm('Your admin account can’t send messages at any scope. Ask a Super Admin to enable City-wise or Zone-wise sending.');if(!al.includes(c.scope))c.scope=al[0];
 const e=ent(c.target)||D().users.find(u=>u.id===c.target),tn=e?(e.name&&e.name.en?e.name.en:e.name):c.target,a=audOf(),msg=UI.cmMsg??TPL[c.tpl][1],prev=msg.replace('{shop}',tn).replace('{offer}','10% off').replace('{link}',shareUrl('biz-'+(ent(c.target)?c.target:'b1')));
 const items=[...D().users.map(u=>({id:u.id,label:u.name,sub:'+91 '+u.phone,group:'Customers'})),...D().biz.map(b=>({id:b.id,label:b.name.en,sub:catName(b.cat),group:'Shops'})),...D().svc.map(s=>({id:s.id,label:s.name.en,sub:catName(s.cat),group:'Service providers'}))];
 const cfg={label:'Send to customers of',placeholder:'Search customers, shops or service providers',value:c.target,items,recent:(S.cmRecent&&S.cmRecent.cmt)||[],onPick:id=>{UI.cm.target=id;render(true)}};
 return `<div class="stack-lg"><h1>${t('Communications')}</h1><div class="cols2"><div class="stack"><div class="card pad stack"><h3>1. ${t('Scope')}</h3>${segBtn('cmScope',c.scope,[['all','Overall'],['city','City-wise'],['zone','Zone-wise']]).replace(/<button role="tab" aria-selected="(true|false)" class="(on|)" data-act="cmScope" data-v="(\w+)">([^<]*)<\/button>/g,(m,a,b,v,l)=>al.includes(v)?m:`<button role="tab" disabled title="${t('Super Admin only')}" class="" data-act="cmScope" data-v="${v}">🔒 ${l}</button>`)}${S.role!=='super'?`<div class="small muted">${ic('lock',12)} ${t('Your admin account can send')}: ${al.map(s=>t(s==='city'?'City-wise':'Zone-wise')).join(', ')}.</div>`:''}
  ${c.scope==='city'?`<div><div class="lbl small">${t('Pick one or more cities')}</div><div class="chips" style="flex-wrap:wrap">${scopeCities().map(x=>`<label class="chip ${c.cities.includes(x.id)?'on':''}"><input class="sr" type="checkbox" ${c.cities.includes(x.id)?'checked':''} data-chg="cmCity" data-id="${x.id}">${esc(nm(x))}</label>`).join('')}</div></div>`:''}${c.scope==='zone'?`<div><div class="lbl small">${t('Pick one or more zones')}</div><div class="chips" style="flex-wrap:wrap">${scopeZones().map(z=>`<label class="chip ${c.zones.includes(z.id)?'on':''}"><input class="sr" type="checkbox" ${c.zones.includes(z.id)?'checked':''} data-chg="cmZone" data-id="${z.id}">${esc(z.name)}</label>`).join('')||`<span class="muted small">${t('No zones in your cities yet.')}</span>`}</div></div>`:''}</div>
 <div class="card pad stack"><h3>2. ${t('Audience')}</h3>${comboHtml('cmt',cfg)}<div class="grid g3 center"><div class="card pad"><b>${a.n}</b><div class="xs muted">${t('Total audience')}</div></div><div class="card pad"><b style="color:var(--success)">${UI.cm.ch.wa?a.wa:0}</b><div class="xs muted">${t('WhatsApp opted-in')}</div></div><div class="card pad"><b>${a.n-a.wa}</b><div class="xs muted">${t('Excluded (no opt-in)')}</div></div></div>${alertBox('info',t('Only customers who opted in to WhatsApp offers are counted. Opted-out numbers are never messaged.'),'shield')}</div>
 <div class="card pad stack"><h3>3. ${t('Channels')}</h3>${[['wa','WhatsApp Business',a.wa],['app','In-app notification',a.app],['email','Email',a.em]].map(([k,l,x])=>`<label class="check"><input type="checkbox" ${c.ch[k]?'checked':''} data-chg="cmch" data-k="${k}" style="accent-color:var(--primary)"> ${l} <span class="muted small">(${x})</span></label>`).join('')}</div>
 <div class="card pad stack"><h3>4. ${t('Template & message')}</h3><div class="chips">${Object.entries(TPL).map(([k,v])=>`<button class="chip ${c.tpl===k?'on':''}" data-act="cmtpl" data-v="${k}">${t(v[0])}</button>`).join('')}</div><textarea class="input" data-in="cmmsg" aria-label="${t('Message')}" rows="4">${esc(msg)}</textarea><div class="xs muted">${t('Variables')}: {shop} {offer} {link}. ${t('WhatsApp templates need prior approval from Meta.')}</div></div>
 <div class="card pad stack"><h3>5. ${t('Schedule')}</h3><div class="chips"><button class="chip ${c.sched==='now'?'on':''}" data-act="cmsch" data-v="now">${t('Send now')}</button><button class="chip ${c.sched==='later'?'on':''}" data-act="cmsch" data-v="later">${t('Schedule')}</button></div>${c.sched==='later'?`<input class="input" type="datetime-local" data-in="cmwhen" value="${esc(c.when)}" aria-label="${t('Date and time')}">`:''}</div></div>
 <div class="stack"><div class="card pad stack" style="position:sticky;top:76px"><h3>${t('Preview')}</h3><div style="background:#DCF8C6;color:#111;padding:12px 14px;border-radius:12px 12px 12px 2px;white-space:pre-wrap;font-size:.92rem">${esc(prev)}<div class="xs" style="opacity:.6;margin-top:4px">${t('Reply STOP to opt out')} · ${ftime(Date.now())}</div></div><button class="btn p block" data-act="cmReview" ${can('comms')&&(c.ch.wa||c.ch.app||c.ch.email)&&a.n>0?'':'disabled'}>${ic('eye',18)} ${t('Review before sending')}</button>${a.n===0?`<div class="small" style="color:var(--error)">${t('Audience is empty for this scope.')}</div>`:''}</div></div></div>
 <div class="card pad stack"><h3>${t('Delivery reports')}</h3>${tbl(['When','Target','Scope','Channels','Sent','Delivered','Failed','Opt-outs','Status'],D().comms.map(m=>[fdt(m.ts),esc(m.target),esc(m.scope||'Overall (all cities)'),m.ch.join(', '),m.sent,m.delivered,m.failed,m.optout,`<span class="badge ${m.status==='sent'?'ok':'warn'}">${t(m.status==='sent'?'Sent':'Scheduled')}</span>`]))}</div></div>`});
A.cmScope=el=>{UI.cm.scope=el.dataset.v;render(true)};
CH.cmCity=el=>{const c=UI.cm;c.cities=el.checked?[...new Set([...c.cities,el.dataset.id])]:c.cities.filter(x=>x!==el.dataset.id);render(true)};CH.cmZone=el=>{const c=UI.cm;c.zones=el.checked?[...new Set([...c.zones,el.dataset.id])]:c.zones.filter(x=>x!==el.dataset.id);render(true)};
A.cmReview=()=>{const c=UI.cm,a=audOf(),e=ent(c.target)||D().users.find(u=>u.id===c.target),chs=[c.ch.wa&&'WhatsApp',c.ch.app&&'In-app',c.ch.email&&'Email'].filter(Boolean);
 sheet(`<h3>${t('Review before sending')}</h3><dl class="kv" style="margin-top:10px"><dt>${t('Scope')}</dt><dd>${esc(scopeText())}</dd><dt>${t('Audience')}</dt><dd>${esc(e?(e.name&&e.name.en?e.name.en:e.name):c.target)}</dd><dt>${t('Recipients')}</dt><dd>${a.n} (${c.ch.wa?a.wa+' '+t('opted in on WhatsApp'):''}${c.ch.wa?', ':''}${a.n-a.wa} ${t('excluded')})</dd><dt>${t('Channels')}</dt><dd>${chs.join(', ')}</dd><dt>${t('Schedule')}</dt><dd>${c.sched==='later'&&c.when?fdt(new Date(c.when).getTime()):t('Send now')}</dd><dt>${t('Template')}</dt><dd>${t(TPL[c.tpl][0])}</dd></dl>${alertBox('warn',t('Messages can’t be recalled after sending. Opt-outs are respected automatically.'))}<div class="row" style="margin-top:12px"><button class="btn g grow" data-act="closeSheet">${t('Back')}</button><button class="btn p grow" data-act="cmsend2">${ic('send',18)} ${c.sched==='later'?t('Confirm & schedule'):t('Confirm & send')}</button></div>`,{label:'Review before sending'})};
A.cmsend2=()=>{const c=UI.cm,a=audOf(),e=ent(c.target)||D().users.find(u=>u.id===c.target),tn=e?(e.name&&e.name.en?e.name.en:e.name):c.target;const chs=[c.ch.wa&&'WhatsApp',c.ch.app&&'In-app',c.ch.email&&'Email'].filter(Boolean);const sent=(c.ch.wa?a.wa:0)+(c.ch.app?a.app:0)+(c.ch.email?a.em:0);D().comms.unshift({id:rid('c'),ts:c.sched==='later'&&c.when?new Date(c.when).getTime():Date.now(),target:tn,scope:scopeText(),ch:chs,tpl:c.tpl,sent,delivered:Math.round(sent*.95),failed:Math.round(sent*.05),optout:Math.round(sent*.01),status:c.sched==='later'?'scheduled':'sent'});if(c.ch.app)notify('cust','Offer from '+tn,(UI.cmMsg??TPL[c.tpl][1]).replace('{shop}',tn).replace('{offer}','10% off').replace('{link}',''),'offers','offer');audit('Campaign '+(c.sched==='later'?'scheduled':'sent'),tn+' · '+scopeText(),{},{recipients:sent});save();closeSheet();render(true);toast(c.sched==='later'?t('Campaign scheduled'):t('Campaign sent'),'send')};
